            o.transition(b); ok = True
        except InvalidTransition:
            ok = False
        assert ok == (b in TRANSITIONS[a]), (a, b)
        assert o.state == (b if ok else a)
o = Order(1); o.pay(); o.ship(); o.deliver(); o.refund()
